                return obj["from_user"].to_numpy()
            return np.array([], dtype=object)

        if isinstance(obj, pd.Series):
            if obj.name == "from_user":
                return obj.to_numpy()
            if "from_user" in obj.index:
                value = obj["from_user"]
                if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
                    return np.asarray(value, dtype=object)
                return np.asarray([value], dtype=object)
            obj = obj.to_list()

        if isinstance(obj, dict):
            if "from_user" not in obj:
                return np.array([], dtype=object)
            value = obj["from_user"]
            if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
                return np.asarray(value, dtype=object)
            return np.asarray([value], dtype=object)

        if isinstance(obj, (list, tuple, np.ndarray)):
            seq = list(obj)
            if not seq:
                return np.array([], dtype=object)

            first_non_missing = next((item for item in seq if item is not None), None)
            if first_non_missing is None:
                return np.array([], dtype=object)

            if isinstance(first_non_missing, (dict, pd.Series)) or hasattr(first_non_missing, "from_user"):
                collected = []
                for item in seq:
                    if item is None:
                        continue
                    if isinstance(item, dict):
                        if "from_user" in item:
                            collected.append(item["from_user"])
                        continue
                    if isinstance(item, pd.Series):
                        if "from_user" in item.index:
                            collected.append(item["from_user"])
                        continue
                    if hasattr(item, "from_user"):
                        collected.append(getattr(item, "from_user"))
                        continue
                    try:
                        collected.append(item["from_user"])
                    except Exception:
                        continue
                return np.asarray(collected, dtype=object)

            return np.asarray(seq, dtype=object)

        if hasattr(obj, "__getitem__"):
            try:
                value = obj["from_user"]
                if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
                    return np.asarray(value, dtype=object)
                return np.asarray([value], dtype=object)
            except Exception:
                pass

        return np.array([], dtype=object)

    def _is_numeric_scalar(value):
        if value is None:
            return False
        if isinstance(value, (bool, np.bool_)):
            return False
        return isinstance(value, (int, float, np.integer, np.floating)) and not isinstance(value, complex)

    raw_values = _extract_from_user_values(result).ravel()

    numeric_values = []
    for value in raw_values:
        if value is None:
            continue
        if isinstance(value, (float, np.floating)) and np.isnan(value):
            continue
        if not _is_numeric_scalar(value):
            raise ValueError('The "from_user" values are not numeric.')
        numeric_values.append(float(value))

    values = np.asarray(numeric_values, dtype=float)

    if values.size == 0:
        mean = median = min_value = max_value = std = np.nan
    else:
        mean = np.mean(values)
        median = np.median(values)
        min_value = np.min(values)
        max_value = np.max(values)
        std = np.std(values, ddof=1) if values.size > 1 else np.nan

    current_time = datetime.now().strftime(DATE_FORMAT)

    return pd.Series(
        {
            "mean": mean,
            "median": median,
            "min": min_value,
            "max": max_value,
            "std": std,
            "current_time": current_time,
